{
  "assessment": "Widespread discontent across all segments of Tunisian society despite a nominally calm surface and solid legislative backing requires urgent fiscal rebalancing. We must direct public funds toward infrastructure and welfare to appease urban workers, youth, and rural populations while maintaining fiscal stability. A warm response to Angola will further cement our diplomatic standing within the African Union.",
  "directives": [
    {
      "type": "set_spending",
      "target": null,
      "amount": 2.5,
      "sub": "welfare",
      "order": "Allocate 2.5 percent of GDP to welfare spending to support vulnerable populations and alleviate urban and rural poverty."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 3.0,
      "sub": "infrastructure",
      "order": "Allocate 3.0 percent of GDP to infrastructure investment to stimulate employment and economic growth."
    },
    {
      "type": "trade_deal_accept",
      "target": "AGO",
      "amount": 0,
      "order": "Accept the bilateral trade partnership proposal with Angola."
    }
  ],
  "cables": [
    {
      "to": "AGO",
      "private": false,
      "text": "Tunisia warmly accepts Angola's offer to deepen our bilateral partnership. We look forward to strengthening trade and security ties within the African Union."
    }
  ],
  "public_statement": "The Government of Tunisia is steadfastly committed to improving the living standards of all citizens. Today, we are rolling out significant investments in public welfare and national infrastructure to generate jobs, support working families, and foster enduring prosperity across every region of our republic.",
